<?php if (!defined('ABSPATH')) exit; $cat=Psc_Messages::get_categories()[$message->categorie]; ?>
<div class="wrap psc-messages-admin"><?php psc_admin_notice_map(Psc_Messages_Admin::notices(), isset($_GET['psc_msg']) ? sanitize_key(wp_unslash($_GET['psc_msg'])) : ''); ?><a href="<?php echo esc_url(admin_url('admin.php?page=psc_messages')); ?>">← <?php esc_html_e('Tous les messages', 'periscolaire-registration'); ?></a><p><span class="psc-cat" style="--cat-bg:<?php echo esc_attr($cat['bg']); ?>;--cat-fg:<?php echo esc_attr($cat['fg']); ?>"><?php echo esc_html($cat['label']); ?></span> <?php printf(esc_html__('Envoyé le %1$s à %2$s · par %3$s', 'periscolaire-registration'), esc_html(date_i18n('d/m/Y',strtotime($message->date_envoi))), esc_html(date_i18n('H\hi',strtotime($message->date_envoi))), esc_html($author ? $author->display_name : '—')); ?></p><h1><?php echo esc_html($message->titre); ?></h1><div class="psc-message-rendered"><?php echo wp_kses($message->corps,Psc_Messages::allowed_html()); ?></div>
<div class="psc-message-tiles"><div><small><?php esc_html_e('Destinataires', 'periscolaire-registration'); ?></small><strong><?php echo (int) $stats['total']; ?></strong></div><div><small><?php esc_html_e('Ont vu', 'periscolaire-registration'); ?></small><strong><?php echo (int) $stats['vus']; ?> · <?php echo (int) $stats['taux']; ?> %</strong></div><div><small><?php esc_html_e('Non lu', 'periscolaire-registration'); ?></small><strong class="psc-message-danger"><?php echo (int) $stats['non_lus']; ?></strong></div><div><small><?php esc_html_e('1re lecture', 'periscolaire-registration'); ?></small><strong><?php $d=$stats['delai_median_minutes']; echo esc_html($d===null?'—':($d<60
    /* translators: %d: minutes */
    ? sprintf(__('%d min', 'periscolaire-registration'), (int) $d)
    /* translators: 1: heures, 2: minutes */
    : sprintf(__('%1$d h %2$d', 'periscolaire-registration'), (int) floor($d/60), (int) ($d%60)))); ?></strong></div><div><small><?php esc_html_e('Conversations liées', 'periscolaire-registration'); ?></small><strong><?php if ($conversations_count): ?><a href="<?php echo esc_url(add_query_arg(array('page' => 'psc_conversations', 'filtre' => 'toutes', 'message_id' => (int) $message->id), admin_url('admin.php'))); ?>"><?php echo (int) $conversations_count; ?></a><?php else: ?>0<?php endif; ?></strong></div></div>
<p><?php foreach(array('tous'=>__('Tous', 'periscolaire-registration'),'vus'=>__('A vu', 'periscolaire-registration'),'non_lus'=>__('Non lu', 'periscolaire-registration')) as $key=>$label): ?><a class="button<?php echo $filter===$key?' button-primary':''; ?>" href="<?php echo esc_url(add_query_arg(array('page'=>'psc_message_stats','id'=>$message->id,'filter'=>$key),admin_url('admin.php'))); ?>"><?php echo esc_html($label); ?></a> <?php endforeach; ?></p>
<div class="psc-stats-actions"><form method="post" action="<?php echo esc_url(admin_url('admin-post.php')); ?>"><input type="hidden" name="action" value="psc_resend_message"><input type="hidden" name="id" value="<?php echo (int)$message->id; ?>"><?php wp_nonce_field('psc_resend_message'); ?><button class="button"><?php echo esc_html(sprintf(
    /* translators: %d: nombre de familles qui n'ont pas lu le message */
    _n('Relancer %d non-lecteur', 'Relancer les %d non-lecteurs', (int) $stats['non_lus'], 'periscolaire-registration'), (int) $stats['non_lus'])); ?></button></form><form method="post" action="<?php echo esc_url(admin_url('admin-post.php')); ?>"><input type="hidden" name="action" value="psc_export_message"><input type="hidden" name="id" value="<?php echo (int)$message->id; ?>"><?php wp_nonce_field('psc_export_message'); ?><button class="button"><?php esc_html_e('Exporter CSV','periscolaire-registration'); ?></button></form></div>
<table class="wp-list-table widefat fixed striped"><caption class="screen-reader-text"><?php esc_html_e('Lecture du message par famille destinataire', 'periscolaire-registration'); ?></caption><thead><tr><th scope="col"><?php esc_html_e('Famille', 'periscolaire-registration'); ?></th><th scope="col"><?php esc_html_e('Enfants', 'periscolaire-registration'); ?></th><th scope="col"><?php esc_html_e('Statut', 'periscolaire-registration'); ?></th><th scope="col"><?php esc_html_e('Vu le', 'periscolaire-registration'); ?></th></tr></thead><tbody><?php foreach($recipients as $r): ?><tr><td><strong><?php echo esc_html(trim($r->prenom.' '.$r->nom)); ?></strong><br><small><?php echo esc_html($r->email); ?></small></td><td><?php echo esc_html(Psc_Messages_Admin::children_label($r->family_id)); ?></td><td><span class="psc-status <?php echo $r->vu_le?'psc-status-vus':'psc-status-non-lus'; ?>"><?php echo $r->vu_le ? esc_html__('A vu', 'periscolaire-registration') : esc_html__('Non lu', 'periscolaire-registration'); ?></span></td><td><?php if($r->vu_le): echo esc_html(date_i18n('d/m/Y H:i',strtotime($r->vu_le))); ?><br><small><?php echo esc_html($r->vu_canal); ?></small><?php else: ?>—<br><small><?php echo $r->email_statut==='envoye' ? esc_html__('E-mail délivré', 'periscolaire-registration') : ($r->email_statut==='echec' ? esc_html($r->email_erreur ?: __('Échec de l’envoi', 'periscolaire-registration')) : '—'); ?></small><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div>
